// Metasploit engagement map (generated by scripts/build-cpts.mjs). Without
// scripts the page is the whole map: every node's explanation is a <details>
// and the module workflow is a plain list of steps. This adds:
//  - the workflow walk: the steps become tabs over one panel, with Previous /
//    Next, and the map marks, opens and scrolls to the node for each step;
//  - copy buttons on the command blocks, with the reader's targets from the
//    CPTS page (saved there on this device) swapped in;
//  - open / close all, and a flash on the phase a loop link jumps to.
import { initCommandPalette } from "../../js/command-palette.js?v=search2";
import { initSiteHeader } from "../../js/site-header.js?v=276fa973-header";
import { initTheme } from "../../js/theme.js?v=276fa973";
import { copyTextToClipboard } from "../../js/markdown.js?v=276fa973-th";
import { initHeroDither } from "../../js/hero-dither.js?v=276fa973-idle";

const reduceMotion = () => window.matchMedia("(prefers-reduced-motion: reduce)").matches;

// The CPTS page saves the reader's targets under "cpts-vars"; reuse them so a
// command here reads the same as there. A per-viewer convenience: guarded.
const TOKENS = { TARGET: "target", ATTACKER_IP: "ip", DOMAIN: "domain" };
const loadVars = () => {
  try { return JSON.parse(localStorage.getItem("cpts-vars") || "{}") || {}; } catch { return {}; }
};
const fillTokens = (root) => {
  const vars = loadVars();
  for (const code of root.querySelectorAll(".msf-cmd code")) {
    code.textContent = code.textContent.replace(/(?<![\w.])(TARGET|ATTACKER_IP|DOMAIN)(?![\w.])/g,
      (token) => (typeof vars[TOKENS[token]] === "string" && vars[TOKENS[token]].trim()) || token);
  }
};

const addCopy = (pre) => {
  if (pre.parentElement?.classList.contains("msf-cmd-wrap")) return;
  const wrap = document.createElement("div");
  wrap.className = "msf-cmd-wrap";
  pre.before(wrap);
  wrap.append(pre);
  const btn = document.createElement("button");
  btn.type = "button";
  btn.className = "msf-copy";
  btn.textContent = "Copy";
  btn.addEventListener("click", () => {
    // Copy the commands without the msf6 / meterpreter prompts.
    const text = (pre.querySelector("code")?.textContent || "")
      .split("\n").map((line) => line.replace(/^(msf6(?: [^>]*)?|meterpreter) > /, "")).join("\n").trim();
    void copyTextToClipboard(text, btn, "Copy");
  });
  wrap.append(btn);
};

const openNode = (li) => {
  // Open the node's own explanation; its ancestors' trees are always drawn.
  const box = li.querySelector(":scope > .msf-node-box");
  if (box) box.open = true;
};

const initWalk = () => {
  const walk = document.getElementById("msf-walk");
  if (!walk) return;
  const steps = [...walk.querySelectorAll(".msf-walk-step")];
  if (!steps.length) return;
  const controls = walk.querySelector(".msf-walk-controls");
  const prev = walk.querySelector('[data-walk="prev"]');
  const next = walk.querySelector('[data-walk="next"]');
  const pos = walk.querySelector(".msf-walk-pos");

  const panel = document.createElement("div");
  panel.className = "msf-walk-panel";
  panel.id = "msf-walk-panel";
  panel.setAttribute("aria-live", "polite");
  walk.querySelector(".msf-walk-steps").after(panel);

  let current = -1;
  const show = (index, { scroll = true } = {}) => {
    current = Math.max(0, Math.min(steps.length - 1, index));
    const step = steps[current];
    steps.forEach((s, i) => {
      const tab = s.querySelector(".msf-walk-tab");
      if (i === current) tab.setAttribute("aria-current", "step");
      else tab.removeAttribute("aria-current");
      s.classList.toggle("is-done", i < current);
    });

    const title = document.createElement("h3");
    title.textContent = `${current + 1}. ${step.querySelector(".msf-walk-tab span:last-child")?.textContent || ""}`;
    const card = step.querySelector(".msf-walk-card").cloneNode(true);
    card.classList.remove("msf-walk-card");
    panel.replaceChildren(title, card);
    for (const pre of panel.querySelectorAll("pre.msf-cmd")) addCopy(pre);

    pos.textContent = `Step ${current + 1} of ${steps.length}`;
    prev.disabled = current === 0;
    next.disabled = current === steps.length - 1;

    for (const node of document.querySelectorAll(".msf-node.is-current")) node.classList.remove("is-current");
    const node = document.getElementById(`node-${step.dataset.node}`);
    if (node) {
      node.classList.add("is-current");
      openNode(node);
      if (scroll) node.scrollIntoView({ behavior: reduceMotion() ? "auto" : "smooth", block: "center" });
    }
  };

  for (const [i, step] of steps.entries()) {
    step.querySelector(".msf-walk-tab").addEventListener("click", (event) => {
      event.preventDefault();
      show(i, { scroll: false });
    });
  }
  prev.addEventListener("click", () => show(current - 1));
  next.addEventListener("click", () => show(current + 1));

  // A step's badge on the map starts the walk there.
  for (const badge of document.querySelectorAll(".msf-node.is-step")) {
    badge.querySelector(":scope > .msf-node-box")?.addEventListener("toggle", (event) => {
      if (!event.target.open) return;
      const n = Number(badge.dataset.step) - 1;
      if (n !== current) show(n, { scroll: false });
    });
  }

  walk.classList.add("is-enhanced");
  controls.hidden = false;
  show(0, { scroll: false });
};

const initMapTools = () => {
  const tools = document.querySelector(".msf-map-tools");
  if (!tools) return;
  tools.hidden = false;
  for (const btn of tools.querySelectorAll("[data-expand]")) {
    btn.addEventListener("click", () => {
      const open = btn.dataset.expand === "open";
      for (const box of document.querySelectorAll(".msf-node-box")) box.open = open;
    });
  }
};

const initLoops = () => {
  for (const link of document.querySelectorAll(".msf-next")) {
    link.addEventListener("click", () => {
      const phase = document.getElementById(`phase-${link.dataset.to}`);
      if (!phase || reduceMotion()) return;
      phase.classList.remove("is-flash");
      void phase.offsetWidth;
      phase.classList.add("is-flash");
    });
  }
};

document.addEventListener("DOMContentLoaded", () => {
  initCommandPalette();
  initSiteHeader();
  initTheme();
  initHeroDither();
  fillTokens(document);
  for (const pre of document.querySelectorAll(".msf-map pre.msf-cmd")) addCopy(pre);
  initMapTools();
  initLoops();
  initWalk();
});
